import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import * as Schema from "effect/Schema";
import { initialTransition, isUnhandled, transition } from "xstate";
import type { AnyStateMachine, EventFromLogic, SnapshotFrom } from "xstate";

const isIntent = Schema.is(Schema.Struct({ type: Schema.Literals(["patch", "notice.post", "notice.resolve", "input.send", "place.countCatchUp", "place.release", "procedure.start"]) }));

export const initial = <M extends AnyStateMachine>(...input: Parameters<typeof initialTransition<M>>) => {
  const [snapshot, effects] = initialTransition(...input);

  if (effects.length > 0) { throw new Error("Durable machines must initialize without effects"); }

  return snapshot;
};

export const decideMachine = <M extends AnyStateMachine>(machine: M, snapshot: SnapshotFrom<M>, event: EventFromLogic<M>) => {
  const result = transition(machine, snapshot, event);

  for (const effect of result[1]) {
    if (effect.kind !== "emit" || !isIntent(effect.event)) { throw new Error(`Durable machines cannot execute ${effect.type}`); }
  }

  return isUnhandled(snapshot, result) ? Option.none() : Option.some({ snapshot: result[0], intents: result[1].map((effect) => {
    if (effect.kind !== "emit") { throw new Error("Expected an emitted intent"); }

    return effect.event;
  }) });
};

// The supplied apply owns the single transaction, including CAS, journal and durable intents.
export const commit = <Row, A, E, R>(
  read: Effect.Effect<Row, E, R>,
  persist: (row: Row) => Effect.Effect<A, E, R>,
  conflict: (error: E) => boolean
): Effect.Effect<A, E, R> => {
  const attempt = Effect.gen(function* attempt() {
    const row = yield* read;

    return yield* persist(row);
  });

  return attempt.pipe(Effect.catchIf(conflict, () => attempt));
};
